#!/usr/bin/env python3
"""
Neutron Cross-Section Data Processor
Processes neutron cross-section data files and calculates macroscopic cross-sections and reaction rates.
"""

import os
import json
import re

# Constants
THERMAL_ENERGY = 0.025  # eV
THERMAL_TOLERANCE = 0.1  # eV
AVOGADRO = 6.02214076e23  # atoms/mol
BARN_TO_CM2 = 1e-24

# Status priorities (higher number = higher priority)
STATUS_PRIORITY = {
    'corrupted': 10,
    'invalid_format': 9,
    'read_error': 8,
    'cross_section_mismatch': 7,
    'invalid_energy_ordering': 6,
    'negative_cross_section': 5,
    'duplicate_isotope': 4,
    'insufficient_data': 3,
    'missing_density_data': 2,
    'invalid_isotope_name': 1,
    'valid': 0
}

# Element symbols to Z mapping
ELEMENTS = {
    'h': 1, 'he': 2, 'li': 3, 'be': 4, 'b': 5, 'c': 6, 'n': 7, 'o': 8, 'f': 9,
    'ne': 10, 'na': 11, 'mg': 12, 'al': 13, 'si': 14, 'p': 15, 's': 16, 'cl': 17,
    'ar': 18, 'k': 19, 'ca': 20, 'sc': 21, 'ti': 22, 'v': 23, 'cr': 24, 'mn': 25,
    'fe': 26, 'co': 27, 'ni': 28, 'cu': 29, 'zn': 30, 'ga': 31, 'ge': 32, 'as': 33,
    'se': 34, 'br': 35, 'kr': 36, 'rb': 37, 'sr': 38, 'y': 39, 'zr': 40, 'nb': 41,
    'mo': 42, 'tc': 43, 'ru': 44, 'rh': 45, 'pd': 46, 'ag': 47, 'cd': 48, 'in': 49,
    'sn': 50, 'sb': 51, 'te': 52, 'i': 53, 'xe': 54, 'cs': 55, 'ba': 56, 'la': 57,
    'ce': 58, 'pr': 59, 'nd': 60, 'pm': 61, 'sm': 62, 'eu': 63, 'gd': 64, 'tb': 65,
    'dy': 66, 'ho': 67, 'er': 68, 'tm': 69, 'yb': 70, 'lu': 71, 'hf': 72, 'ta': 73,
    'w': 74, 're': 75, 'os': 76, 'ir': 77, 'pt': 78, 'au': 79, 'hg': 80, 'tl': 81,
    'pb': 82, 'bi': 83, 'po': 84, 'at': 85, 'rn': 86, 'fr': 87, 'ra': 88, 'ac': 89,
    'th': 90, 'pa': 91, 'u': 92, 'np': 93, 'pu': 94, 'am': 95, 'cm': 96, 'bk': 97,
    'cf': 98, 'es': 99, 'fm': 100, 'md': 101, 'no': 102, 'lr': 103, 'rf': 104,
    'db': 105, 'sg': 106, 'bh': 107, 'hs': 108, 'mt': 109, 'ds': 110, 'rg': 111,
    'cn': 112, 'nh': 113, 'fl': 114, 'mc': 115, 'lv': 116, 'ts': 117, 'og': 118
}


def get_files_sorted(directory):
    """Find all .xs files sorted: deepest dirs first, then reverse alpha by path."""
    xs_files = []
    if not os.path.exists(directory):
        return xs_files

    for root, dirs, files in os.walk(directory):
        for f in files:
            if f.endswith('.xs'):
                full_path = os.path.join(root, f)
                rel_path = os.path.relpath(full_path, directory)
                depth = rel_path.count(os.sep)
                xs_files.append((depth, rel_path, full_path))

    # Sort: depth descending, then path reverse alphabetical
    xs_files.sort(key=lambda x: (x[0], x[1]), reverse=True)
    return [item[2] for item in xs_files]


def parse_xs_file(filepath):
    """Parse a .xs file. Returns (isotopes_list, error)."""
    isotopes = []
    current_isotope = None
    current_data = []

    try:
        with open(filepath, 'r') as f:
            lines = f.readlines()
    except Exception:
        return None, 'read_error'

    for line in lines:
        line_stripped = line.strip()

        # Skip blank lines and comments
        if not line_stripped or line_stripped.startswith('#'):
            continue

        # Check for ISOTOPE line
        if line_stripped.startswith('ISOTOPE:'):
            if current_isotope is not None and current_data:
                isotopes.append((current_isotope, current_data))
            current_isotope = line_stripped[8:].strip()
            current_data = []
            continue

        # Check for ENERGY line
        if line_stripped.startswith('ENERGY:'):
            if current_isotope is None:
                continue

            # Parse fields: ENERGY:<eV> SIGMA_T:<barns> ...
            # Fields can be in any order
            rest = line_stripped[7:].strip()
            parts = rest.split()

            data_point = {'energy': None, 'sigma_t': None, 'sigma_a': None, 'sigma_s': None}

            for part in parts:
                if part.startswith('ENERGY:'):
                    # First token is energy value
                    try:
                        data_point['energy'] = float(part[7:].strip())
                    except ValueError:
                        pass
                elif part.startswith('SIGMA_T:'):
                    try:
                        data_point['sigma_t'] = float(part[8:].strip())
                    except ValueError:
                        pass
                elif part.startswith('SIGMA_A:'):
                    try:
                        data_point['sigma_a'] = float(part[8:].strip())
                    except ValueError:
                        pass
                elif part.startswith('SIGMA_S:'):
                    try:
                        data_point['sigma_s'] = float(part[8:].strip())
                    except ValueError:
                        pass

            current_data.append(data_point)

    # Don't forget last isotope
    if current_isotope is not None and current_data:
        isotopes.append((current_isotope, current_data))

    return isotopes, None


def validate_isotope_data(isotope_name, energy_data):
    """Validate isotope data. Returns (is_valid, errors_list)."""
    errors = []

    if not energy_data:
        errors.append('invalid_format')
        return False, errors

    # Check for NaN/Infinity
    for d in energy_data:
        for key in ['energy', 'sigma_t', 'sigma_a', 'sigma_s']:
            val = d[key]
            if val is not None:
                if val != val:  # NaN
                    errors.append('invalid_format')
                    break
                if val == float('inf') or val == float('-inf'):
                    errors.append('invalid_format')
                    break
        if 'invalid_format' in errors:
            break

    # Check first energy > 0
    first_energy = energy_data[0]['energy']
    if first_energy is None or first_energy <= 0:
        errors.append('invalid_energy_ordering')

    # Check energies strictly increasing
    prev_energy = None
    for d in energy_data:
        energy = d['energy']
        if energy is None:
            errors.append('invalid_format')
            break
        if prev_energy is not None and energy <= prev_energy:
            errors.append('invalid_energy_ordering')
            break
        prev_energy = energy

    if 'invalid_format' in errors:
        return False, errors

    # Check all cross-sections non-negative
    for d in energy_data:
        for key in ['sigma_t', 'sigma_a', 'sigma_s']:
            val = d[key]
            if val is not None and val < 0:
                errors.append('negative_cross_section')
                break
        if 'negative_cross_section' in errors:
            break

    # Check SIGMA_T = SIGMA_A + SIGMA_S within 0.001
    for d in energy_data:
        sigma_t = d['sigma_t']
        sigma_a = d['sigma_a']
        sigma_s = d['sigma_s']
        if sigma_t is not None and sigma_a is not None and sigma_s is not None:
            if abs(sigma_t - (sigma_a + sigma_s)) > 0.001:
                errors.append('cross_section_mismatch')
                break

    return len(errors) == 0, errors


def find_thermal_cross_section(energy_data):
    """Find thermal cross-section at 0.025 eV. Returns (sigma_s, status)."""
    target = THERMAL_ENERGY
    tolerance = THERMAL_TOLERANCE

    candidates = []
    for d in energy_data:
        energy = d['energy']
        sigma_s = d['sigma_s']
        if energy is not None and sigma_s is not None and abs(energy - target) <= tolerance:
            candidates.append((abs(energy - target), energy, sigma_s))

    if not candidates:
        return None, 'insufficient_data'

    # Sort by distance ascending, then energy descending (tie-breaker: higher energy)
    candidates.sort(key=lambda x: (x[0], -x[1]))
    return candidates[0][2], 'valid'


def load_atomic_densities(filepath):
    """Load atomic densities. Returns dict: isotope_name -> (density, atomic_mass)."""
    densities = {}
    if not os.path.exists(filepath):
        return densities

    try:
        with open(filepath, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                parts = line.split(':')
                if len(parts) < 3:
                    continue
                iso_name = parts[0].strip()
                try:
                    density = float(parts[1].strip())
                    atomic_mass = float(parts[2].strip())
                    densities[iso_name] = (density, atomic_mass)
                except ValueError:
                    continue
    except:
        pass
    return densities


def normalize_isotope_name(name):
    """Normalize: lowercase, remove spaces and hyphens."""
    return name.lower().replace(' ', '').replace('-', '')


def parse_isotope_name(name):
    """Parse isotope name to extract Z and A. Returns (Z, A, original_name)."""
    name_lower = name.lower()

    # Try to find mass number at end
    mass_match = re.search(r'(\d+)$', name_lower)
    if mass_match:
        mass = int(mass_match.group(1))
        elem_part = name_lower[:mass_match.start()]

        # Find element symbol
        z = None
        for symbol in sorted(ELEMENTS.keys(), key=len, reverse=True):
            if elem_part.startswith(symbol):
                z = ELEMENTS[symbol]
                break

        if z is not None:
            return (z, mass, name)

    # No mass - find element
    for symbol in sorted(ELEMENTS.keys(), key=len, reverse=True):
        if symbol in name_lower:
            return (ELEMENTS[symbol], 0, name)

    return (None, None, name)


def main():
    data_dir = '/app/data/cross_sections'
    density_file = '/app/data/atomic_densities.txt'
    output_file = '/app/cross_section_report.json'

    xs_files = get_files_sorted(data_dir)
    total_files = len(xs_files)

    atomic_densities = load_atomic_densities(density_file)
    seen_isotopes = {}  # norm_name -> (original_name, source_file)
    isotope_results = []
    invalid_files_count = 0

    for filepath in xs_files:
        rel_path = os.path.relpath(filepath, data_dir)
        isotopes, parse_error = parse_xs_file(filepath)

        if parse_error or isotopes is None:
            invalid_files_count += 1
            continue

        for isotope_name, energy_data in isotopes:
            norm_name = normalize_isotope_name(isotope_name)
            is_duplicate = norm_name in seen_isotopes

            z, a, _ = parse_isotope_name(isotope_name)
            name_valid = (z is not None)

            data_valid, data_errors = validate_isotope_data(isotope_name, energy_data)

            errors = list(data_errors)
            if not name_valid:
                errors.append('invalid_isotope_name')
            if is_duplicate:
                errors.append('duplicate_isotope')

            thermal_xs, thermal_status = find_thermal_cross_section(energy_data)
            if thermal_status == 'insufficient_data':
                errors.append('insufficient_data')

            # Check density
            density_found = False
            if isotope_name in atomic_densities:
                density_found = True
            elif isotope_name.lower() in [k.lower() for k in atomic_densities]:
                density_found = True
            elif norm_name in [normalize_isotope_name(k) for k in atomic_densities]:
                density_found = True

            if not density_found:
                errors.append('missing_density_data')

            # Determine status
            if errors:
                status = max(errors, key=lambda e: STATUS_PRIORITY[e])
            else:
                status = 'valid'

            if norm_name not in seen_isotopes:
                seen_isotopes[norm_name] = (isotope_name, rel_path)

            # Calculate values
            atomic_density = None
            thermal_xs_barns = None
            macroscopic_xs = None
            reaction_rate = None

            if thermal_status == 'valid' and thermal_xs is not None:
                thermal_xs_barns = round(thermal_xs, 6)

            if density_found:
                density, atomic_mass = atomic_densities[isotope_name]
                N_unrounded = (density / atomic_mass) * AVOGADRO
                atomic_density = round(N_unrounded, 6)

                if thermal_xs_barns is not None:
                    sigma_cm2 = thermal_xs_barns * BARN_TO_CM2
                    macroscopic_xs = round(N_unrounded * sigma_cm2, 6)
                    reaction_rate = round(1e14 * macroscopic_xs, 6)

            isotope_results.append({
                'isotope': isotope_name,
                'source_file': rel_path,
                'status': status,
                'atomic_density_atoms_cm3': atomic_density,
                'macroscopic_cross_section_cm_minus1': macroscopic_xs,
                'reaction_rate_reactions_cm3_s': reaction_rate,
                'thermal_xs_barns': thermal_xs_barns,
                'validation_errors': sorted(errors)
            })

    # Sort isotopes: highest Z first, then highest A, then reverse alpha name
    results_with_meta = []
    for r in isotope_results:
        z, a, _ = parse_isotope_name(r['isotope'])
        results_with_meta.append({
            'z': z,
            'a': a,
            'data': r
        })

    # Sort with reverse=True: higher Z first, higher A first, name descending (Z-A)
    results_with_meta.sort(key=lambda x: (
        x['z'] if x['z'] is not None else float('inf'),
        x['a'] if x['a'] is not None else float('inf'),
        x['data']['isotope']
    ), reverse=True)

    sorted_isotopes = [item['data'] for item in results_with_meta]

    output = {
        'total_files': total_files,
        'valid_files': total_files - invalid_files_count,
        'invalid_files': invalid_files_count,
        'total_isotopes': len(isotope_results),
        'valid_isotopes': sum(1 for r in isotope_results if r['status'] == 'valid'),
        'invalid_isotopes': len(isotope_results) - sum(1 for r in isotope_results if r['status'] == 'valid'),
        'isotopes': sorted_isotopes
    }

    # Atomic write
    tmp_file = output_file + '.tmp'
    with open(tmp_file, 'w') as f:
        json.dump(output, f, indent=2)
    os.rename(tmp_file, output_file)


if __name__ == '__main__':
    main()
